import { createMemo, Loading, createEffect } from "solid-js";
import { httpStatus } from "@solidjs/web";
const wait = () => new Promise<number>((r) => setTimeout(() => r(1), 30));
function h() { httpStatus(410); }
function Inner() { const v = createMemo(async () => await wait()); const n = v(); h(); return <b>{n}</b>; }
export default function App() { return <main><Loading fallback={<p>l</p>}><Inner /></Loading></main>; }

